using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Apwenian;

internal sealed class GuoHanGenerationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Apwenian/GuoHanGeneration.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Words/guo2025apwenian");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Binary automatic apwenian sequences arise as the parity of successive whole levels of one finite sum-equivalent morphism.",
        H("Finite Level Generators for Binary Automatic Apwenian Sequences"),
        Blocks(
            Node("guo-han-generation-input", "Canonical binary input", "binaryInput",
                "The input of a positive integer is its binary expansion in most-significant-first order, obtained by reversing Nat.digits 2 n. A Boolean convention chooses either the one-digit word [0] or the empty word for zero.", DescribeRole.Definition),
            Node("guo-han-generation-automatic", "Source automaticity", "IsBinaryAutomatic",
                "A natural-valued sequence u is binary automatic when every u(n) is less than two and there exist a finite state type Q, a DFAO M with natural-valued outputs, and a choice of the zero-input convention such that M on the canonical binary input of every nonnegative n outputs u(n). Only outputs on these inputs are required to be binary. The machine is not required to be invariant under leading-zero padding.", DescribeRole.Definition),
            Node("guo-han-generation-morphism", "Sum-equivalent alphabet morphisms", "AlphabetMorphism",
                "For a finite natural-number alphabet Sigma, a morphism is a map tau from natural numbers to finite words. For every s in Sigma, tau(s) has exactly two letters, every letter of tau(s) belongs to Sigma, and the sum of tau(s) is congruent to s modulo two. Its extension to words is concatenation of the letter images, so it is an endomorphism of the free monoid on Sigma. Values outside Sigma have no role.", DescribeRole.Definition),
            Node("guo-han-generation-level", "Successive ordered levels", "level",
                "For a directive sigma indexed by the nonnegative integers, X(0) is [1] and X(j+1) is obtained by applying sigma(j) to every letter of X(j) and concatenating those images in their original order. This construction is defined for any directive, independently of automaticity and apwenianness.", DescribeRole.Definition),
            Node("guo-han-generation-prefix", "Concatenated-level prefixes", "levelPrefix",
                "The prefix with parameter j is the concatenation X(0) X(1) ... X(j-1). The prefix with parameter zero is empty, and the next prefix appends the next whole level. These are actual words, with their order retained.", DescribeRole.Definition),
            Node("guo-han-generation-generates", "Infinite sequence generated by levels", "Generates",
                "A directive generates a sequence v when each concatenated-level prefix is exactly the initial segment of v having that prefix's length, and for every index n some such prefix has length greater than n. This exact-prefix relation defines the infinite concatenation without a metric-limit construction.", DescribeRole.Definition),
            Node("guo-han-generation-claim", "The universal representation statement", "claim",
                "For every binary automatic u that is apwenian, there exist a finite natural-number alphabet Sigma containing one, a sum-equivalent two-letter morphism tau on every letter of Sigma, and a sequence v generated by the constant directive sigma(j) = tau. Every v(n) belongs to Sigma and satisfies v(n) modulo two = u(n), for all nonnegative n. Any sequence generated by this same directive equals v. Apwenianness is exactly u(0) = 1 and u(n) congruent to u(2n+1) + u(2n+2) modulo two for all nonnegative n. This statement strengthens Conjecture 1 of Guo and Han by allowing a constant directive as its witness.", DescribeRole.Definition),
            Node("guo-han-generation-result", "Every binary automatic apwenian sequence has a level generator", "result",
                "The universal representation statement holds. Adjoin a fresh zero state z with delta(0,z) = z and delta(1,z) equal to the original transition from the start on one. The canonical-input state a(n) then satisfies a(2n+b) = delta(b,a(n)) for b zero or one, including n = b = 0. The finite set of occurring adjacent pairs s(n) = (a(n), a(n+1)) is closed under the ordered children L(q,r) = (delta(1,q), delta(0,r)) and R(q,r) = (delta(0,r), delta(1,r)), with L(s(n)) = s(2n+1) and R(s(n)) = s(2n+2). Enumerate this occurring set with s(0) at index zero, and label a pair by twice its index plus the parity of its first output. The labels are injective, the root label is one, and the apwenian recurrence makes the image [e(L(s)), e(R(s))] sum-equivalent on every alphabet letter. The j-th ordered level is exactly the labels e(s(2^j - 1 + k)) for k from zero through 2^j - 1; its concatenated prefix of j levels contains exactly the first 2^j - 1 values of v. These prefix lengths are unbounded, proving generation, uniqueness, and parity agreement at every index. The alphabet may contain several odd letters, and the generated sequence is not assumed to be a morphism fixed point.", DescribeRole.Theorem,
                new OpenProblemResolutionClaim(ProblemSlugRef.Create("guo-han-binary-automatic-apwenian-level-generation"), ResolutionKind.Proved))
        ), []));

    private static DocumentBlock Node(string id, string title, string declaration, string prose,
        DescribeRole role, OpenProblemResolutionClaim? resolution = null) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
            Blocks(Paragraph(Text(prose))), role, resolution);
}
